-- Read-only verification. All missing_* arrays must be empty; public_finance_rpcs must be 0. Historical baselines were explicitly authorized and recorded on 2026-10-20.
select jsonb_build_object(
'missing_tables',(select coalesce(jsonb_agg(x),'[]') from unnest(array['dashboard_accounts','finance_accounts','finance_ai_insights','finance_alerts','finance_assets','finance_assistant_jobs','finance_attachments','finance_audit_logs','finance_budgets','finance_card_statements','finance_categories','finance_category_rules','finance_credit_cards','finance_dashboard_couple_memberships','finance_financial_snapshots','finance_goal_contributions','finance_goals','finance_installment_plans','finance_installments','finance_investments','finance_liabilities','finance_notification_config','finance_notification_deliveries','finance_processing_events','finance_push_subscriptions','finance_reminders','finance_subscriptions','finance_transaction_attachments','finance_transaction_duplicates','finance_transaction_shares','finance_transaction_splits','finance_transaction_tombstones','finance_whatsapp_alert_deliveries','finance_whatsapp_alerts','finance_whatsapp_budgets','finance_whatsapp_insight_deliveries','finance_whatsapp_insight_settings','finance_whatsapp_spoken_requests','finance_whatsapp_voice_deliveries','finance_whatsapp_voice_preferences']) x where to_regclass('public.'||x) is null),
'missing_functions',(select coalesce(jsonb_agg(x),'[]') from unnest(array['finance_account_create','finance_account_list','finance_alert_dismiss','finance_alert_list','finance_assistant_claim','finance_assistant_delivery_claim','finance_assistant_enqueue','finance_assistant_finish','finance_assistant_record_quality','finance_assistant_request_confirmation','finance_audit_transaction_change','finance_audit_write','finance_balance_summary','finance_budget_create','finance_budget_summary','finance_card_create','finance_card_list','finance_card_statement_list','finance_cashflow_projection','finance_dashboard_clear_login_failures','finance_dashboard_couple_transactions','finance_dashboard_create_transaction','finance_dashboard_delete_transaction','finance_dashboard_list_transactions','finance_dashboard_monthly_summary','finance_dashboard_record_login_failure','finance_dashboard_restore_transaction','finance_dashboard_share_state','finance_dashboard_share_transaction','finance_dashboard_unshare_transaction','finance_dashboard_update_transaction','finance_duplicate_candidates','finance_duplicate_resolve','finance_goal_contribute','finance_goal_create','finance_goal_list','finance_insight_list','finance_installment_list','finance_installment_plan_create','finance_investment_create','finance_investment_list','finance_net_worth','finance_notification_ack','finance_notification_check','finance_notification_claim','finance_preserve_deleted_telegram_update','finance_processing_event_begin','finance_processing_event_complete','finance_push_subscribe','finance_push_unsubscribe','finance_reject_purged_telegram_update','finance_reminder_action','finance_reminder_create','finance_subscription_list','finance_sync_assistant_processing_event','finance_timeline','finance_transaction_fingerprint','finance_transaction_splits_replace','finance_transactions_query','finance_whatsapp_alert','finance_whatsapp_insights','finance_whatsapp_spoken_report','finance_whatsapp_voice']) x where not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname=x)),
'missing_migration_versions',(select coalesce(jsonb_agg(x),'[]') from unnest(array['20260917070158','20260917152553','20260918021554','20260918091144','20260918092754','20260918120432','20260920221136','20260922115528','20260924120000','20260924130000','20260924130100','20260924140000','20260924150000','20261019220107','20261019223045','20261019223308','20261019223434','20261019223558','20261019230125','20261019231107','20261019231251','20261020005847','20261020111147','20261020111206']) x where not exists(select 1 from supabase_migrations.schema_migrations m where m.version=x)),
'public_finance_rpcs',(select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'finance_%' and (has_function_privilege('anon',p.oid,'EXECUTE') or has_function_privilege('authenticated',p.oid,'EXECUTE')))) verification;
